    SELECT DISTINCT ID
    FROM t_alp_check
)
SELECT * FROM t_final;

WITH t_final_id AS (
    SELECT ID
    FROM t_final
)
SELECT * FROM t_final_id;

WITH t_patient_info AS (
    SELECT p.ID, p.Birthday
    FROM Patient p
    JOIN t_final_id t ON p.ID = t.ID
)
SELECT * FROM t_patient_info;

